/**
 * THE PROGRAMMES
 * ==============
 *
 * Four original retro-era experiences, drawn into a 320×240 canvas that
 * becomes the tube's phosphor texture. Everything here is generated by code:
 * no sprites are loaded, no game footage is used, and nothing is derived
 * from any existing title. The reference is the TECHNOLOGY of the period —
 * pseudo-3D scanline roads, grid raycasting, 4-colour tile sprites, test
 * cards — not any particular game.
 *
 * WHY A 2D CANVAS AND NOT A RENDER TARGET
 * ---------------------------------------
 * The obvious R3F answer is four scenes rendered to a WebGLRenderTarget. It
 * would cost four extra scene graphs, four render passes and a lot of
 * machinery to produce output that has to be crushed back down to 320×240
 * to look right. A canvas gets there directly, repaints at 24fps instead of
 * the display rate, and lets each programme be about 60 lines of the actual
 * algorithm the era used. One `texture.needsUpdate = true` per painted
 * frame is the entire integration cost.
 *
 * READABILITY IS THE BRIEF
 * ------------------------
 * These are drawn to be legible THROUGH the CRT shader — after scanlines,
 * bloom, channel separation and a vignette have all taken their cut. So
 * contrast runs higher and detail runs coarser than would look right on a
 * flat screenshot of the canvas alone. The canvas is not the deliverable;
 * the tube is.
 */

export interface DrawArgs {
  ctx: CanvasRenderingContext2D;
  /** Seconds since this programme became active. Resets on every switch. */
  t: number;
  dt: number;
  w: number;
  h: number;
  /** Resolved JetBrains Mono family name, per the project typography lock. */
  mono: string;
  /** True when motion is suppressed: paint one stable, complete frame. */
  frozen: boolean;
}

export interface Programme {
  id: string;
  /** Shown on the tube's own corner readout. */
  label: string;
  draw: (a: DrawArgs) => void;
  reset: () => void;
}

/* ----------------------------------------------------------- utilities ---- */

/** Deterministic hash noise — no allocation, same result every run. */
function hash(n: number): number {
  const s = Math.sin(n * 127.1) * 43758.5453;
  return s - Math.floor(s);
}

function text(
  ctx: CanvasRenderingContext2D,
  s: string,
  x: number,
  y: number,
  size: number,
  color: string,
  mono: string,
  align: CanvasTextAlign = "left",
) {
  ctx.font = `600 ${size}px ${mono}`;
  ctx.textAlign = align;
  ctx.textBaseline = "alphabetic";
  ctx.fillStyle = color;
  ctx.fillText(s, x, y);
}

/** Fill a polygon from a flat coordinate list. */
function poly(ctx: CanvasRenderingContext2D, pts: number[], fill: string, stroke?: string) {
  ctx.beginPath();
  ctx.moveTo(pts[0], pts[1]);
  for (let i = 2; i < pts.length; i += 2) ctx.lineTo(pts[i], pts[i + 1]);
  ctx.closePath();
  ctx.fillStyle = fill;
  ctx.fill();
  if (stroke) {
    ctx.strokeStyle = stroke;
    ctx.lineWidth = 1;
    ctx.stroke();
  }
}

/* ======================================================================== */
/* A — VOYAGE DRIVE                                                         */
/* ======================================================================== */

/**
 * Pseudo-3D scanline road, the technique every 16-bit and early-polygon
 * racer used before hardware transform: the road is not geometry, it is one
 * horizontal band per scanline, each band's width and colour derived from
 * its depth. Curves come from accumulating a horizontal offset per band
 * rather than from rotating anything.
 *
 * The polygonal set dressing — hills, the skyline, the pylons, the player
 * car — IS flat-shaded geometry, projected by hand. That mix is exactly
 * what the 1997-era machines produced, and it is why the result reads as
 * early 3D rather than as a modern fake.
 */
function createDrive(): Programme {
  const st = { z: 0, curve: 0, curveTarget: 0, sway: 0 };

  /* Skyline, generated once and then fixed — a silhouette that reshuffles
     every frame reads as noise, not as a place. */
  const skyline: number[] = [];
  for (let i = 0; i < 40; i += 1) skyline.push(hash(i * 3.7));

  return {
    id: "drive",
    label: "VOYAGE DRIVE",
    reset: () => {
      st.z = 0;
      st.curve = 0;
      st.curveTarget = 0;
      st.sway = 0;
    },
    draw: ({ ctx, t, dt, w, h, mono, frozen }) => {
      const hy = 98; // horizon
      const step = dt === 0 ? 0 : dt;

      // Speed is constant; the sense of acceleration comes from the stripe
      // frequency compressing toward the horizon, not from changing it.
      st.z += step * 34;
      st.curveTarget = Math.sin(t * 0.21) * 2.1 + Math.sin(t * 0.083) * 1.4;
      st.curve += (st.curveTarget - st.curve) * Math.min(1, step * 1.6);
      st.sway = Math.sin(t * 0.7) * 3.2 - st.curve * 2.4;

      /* ---- sky ---- */
      const sky = ctx.createLinearGradient(0, 0, 0, hy);
      sky.addColorStop(0, "#101534");
      sky.addColorStop(0.55, "#3d2f63");
      sky.addColorStop(1, "#b5657a");
      ctx.fillStyle = sky;
      ctx.fillRect(0, 0, w, hy);

      /* ---- sun: banded, because a smooth gradient disc is the one thing
             the hardware of the era could not do ---- */
      const sunX = w * 0.62 - st.curve * 9;
      for (let i = 0; i < 7; i += 1) {
        const r = 26 - i * 1.2;
        ctx.fillStyle = `rgb(${255 - i * 6}, ${150 + i * 10}, ${90 + i * 14})`;
        ctx.beginPath();
        ctx.arc(sunX, hy - 34 + i * 4, r, 0, Math.PI * 2);
        ctx.fill();
        // cut a horizontal slot out of the disc, retro-sunset style
        ctx.fillStyle = sky as unknown as string;
      }
      ctx.save();
      ctx.globalCompositeOperation = "destination-out";
      for (let i = 0; i < 5; i += 1) {
        ctx.fillRect(sunX - 30, hy - 40 + i * 8, 60, 2 + i * 0.6);
      }
      ctx.restore();

      /* ---- distant hills: two parallax layers of flat-shaded polygons ---- */
      for (let layer = 0; layer < 2; layer += 1) {
        const amp = layer === 0 ? 22 : 34;
        const base = hy - (layer === 0 ? 2 : 0);
        const shift = st.curve * (layer === 0 ? 5 : 9);
        ctx.beginPath();
        ctx.moveTo(-10, base);
        for (let i = 0; i <= 20; i += 1) {
          const x = -10 + (i / 20) * (w + 20) - shift;
          const s = skyline[i + layer * 20];
          ctx.lineTo(x, base - 6 - s * amp);
        }
        ctx.lineTo(w + 10, base);
        ctx.closePath();
        ctx.fillStyle = layer === 0 ? "#2a2246" : "#171331";
        ctx.fill();
      }

      /* ---- skyline blocks on the near ridge ---- */
      for (let i = 0; i < 10; i += 1) {
        const bw = 6 + hash(i * 9.1) * 10;
        const bh = 8 + hash(i * 4.3) * 22;
        const x = ((i * 37 + 12 - st.curve * 12) % (w + 40)) - 20;
        ctx.fillStyle = "#0e0b22";
        ctx.fillRect(x, hy - bh, bw, bh);
        // lit windows, fixed per building
        ctx.fillStyle = "#e8c98a";
        for (let k = 0; k < 4; k += 1) {
          if (hash(i * 13 + k * 2.1) > 0.55) {
            ctx.fillRect(x + 2 + (k % 2) * 4, hy - bh + 3 + Math.floor(k / 2) * 6, 2, 3);
          }
        }
      }

      /* ---- ground ---- */
      ctx.fillStyle = "#1c2a1e";
      ctx.fillRect(0, hy, w, h - hy);

      /* ---- the road, one 2px band per depth slice ---- */
      const bandH = 2;
      let dx = 0;
      let curveAccum = 0;
      for (let y = hy + 1; y < h; y += bandH) {
        const p = (y - hy) / (h - hy); // 0 at horizon, 1 at the bumper
        const depth = 1 / Math.max(p, 0.0001);
        // Curve accumulates from the horizon down, which is what makes a
        // straight road bend rather than shear.
        dx += st.curve * 0.055;
        curveAccum += dx * 0.02;
        const cx = w / 2 + curveAccum * 8 + st.sway * p;
        const half = 14 + p * 168;

        // segment phase — stripes compress toward the horizon for free
        const seg = Math.floor(depth * 2.6 + st.z * 0.09) % 2;
        const grass = seg ? "#22361f" : "#1c2a1e";
        const rumble = seg ? "#d8d2c0" : "#a8413f";
        const road = seg ? "#3b3b42" : "#353539";

        ctx.fillStyle = grass;
        ctx.fillRect(0, y, w, bandH);
        ctx.fillStyle = rumble;
        ctx.fillRect(cx - half * 1.12, y, half * 2.24, bandH);
        ctx.fillStyle = road;
        ctx.fillRect(cx - half, y, half * 2, bandH);

        // centre dashes, at half the rumble frequency
        if (Math.floor(depth * 1.3 + st.z * 0.045) % 2 === 0 && p > 0.06) {
          ctx.fillStyle = "#e6e0cb";
          ctx.fillRect(cx - half * 0.035, y, Math.max(1, half * 0.07), bandH);
        }
      }

      /* ---- roadside pylons. Projected properly, so they scale and pass
             the camera instead of scrolling as a texture ---- */
      for (let i = 0; i < 9; i += 1) {
        const worldZ = i * 26 + 14 - ((st.z * 0.9) % 26);
        if (worldZ < 2) continue;
        const p = Math.min(1, 26 / worldZ);
        const y = hy + p * (h - hy);
        if (y > h + 10) continue;
        // re-walk the curve to this depth so the pylon sits on the verge
        const c = st.curve * (1 - p) * 62;
        const half = 14 + p * 168;
        const side = i % 2 === 0 ? -1 : 1;
        const x = w / 2 + c + side * half * 1.35;
        const ph = 34 * p;
        const pw = Math.max(1, 5 * p);
        ctx.fillStyle = "#6f6a58";
        ctx.fillRect(x - pw / 2, y - ph, pw, ph);
        ctx.fillStyle = side < 0 ? "#e8b84a" : "#c8d0d4";
        ctx.fillRect(x - pw, y - ph - Math.max(1, 5 * p), pw * 2, Math.max(1, 5 * p));
      }

      /* ---- the car: flat-shaded polygons, three tones, no gradient ---- */
      if (!frozen) ctx.save();
      const bob = frozen ? 0 : Math.sin(t * 8.3) * 0.8;
      const cxCar = w / 2 + st.sway * 1.6;
      const cyCar = h - 14 + bob;
      // shadow
      ctx.fillStyle = "rgba(0,0,0,0.45)";
      ctx.beginPath();
      ctx.ellipse(cxCar, cyCar + 12, 46, 6, 0, 0, Math.PI * 2);
      ctx.fill();
      // body
      poly(
        ctx,
        [
          cxCar - 44, cyCar + 10,
          cxCar - 38, cyCar - 10,
          cxCar - 22, cyCar - 20,
          cxCar + 22, cyCar - 20,
          cxCar + 38, cyCar - 10,
          cxCar + 44, cyCar + 10,
        ],
        "#c8455f",
      );
      // roof / rear window
      poly(
        ctx,
        [cxCar - 22, cyCar - 20, cxCar - 16, cyCar - 30, cxCar + 16, cyCar - 30, cxCar + 22, cyCar - 20],
        "#8e2f45",
      );
      ctx.fillStyle = "#2b3a4a";
      ctx.fillRect(cxCar - 15, cyCar - 29, 30, 8);
      // lit brake strip and lamps — the only saturated pixels on screen
      ctx.fillStyle = "#ff5c5c";
      ctx.fillRect(cxCar - 36, cyCar - 6, 12, 6);
      ctx.fillRect(cxCar + 24, cyCar - 6, 12, 6);
      ctx.fillStyle = "#ffd0d0";
      ctx.fillRect(cxCar - 8, cyCar - 15, 16, 2);
      // wheels
      ctx.fillStyle = "#141418";
      ctx.fillRect(cxCar - 46, cyCar + 2, 8, 12);
      ctx.fillRect(cxCar + 38, cyCar + 2, 8, 12);
      if (!frozen) ctx.restore();

      /* ---- HUD ---- */
      const speed = 168 + Math.round(Math.sin(t * 1.7) * 9);
      text(ctx, "SPEED", 10, 22, 10, "#8fb7c8", mono);
      text(ctx, `${speed}`, 10, 36, 16, "#f4efe2", mono);
      text(ctx, "ROUTE", w - 10, 22, 10, "#8fb7c8", mono, "right");
      text(ctx, "V-01", w - 10, 36, 16, "#f4efe2", mono, "right");
    },
  };
}

/* ======================================================================== */
/* B — ARCHIVE MAZE                                                         */
/* ======================================================================== */

/**
 * A grid raycaster — the 1992 corridor renderer, implemented properly: DDA
 * across a cell grid, perpendicular distance for the wall height (using the
 * euclidean distance is what gives the classic fisheye bug), and a vertical
 * strip per screen column.
 *
 * The maze, the wall treatment and the objects in it are original. There
 * are no enemies, no weapon, no HUD borrowed from anything — this is the
 * Voyagerscape archive rendered with period hardware, so the "monsters" are
 * filing monoliths and the corridor is a storage stack.
 *
 * 160 rays at 2px wide rather than 320 at 1px: at this texture size the
 * difference is invisible through the shader and it halves the cost.
 */
function createMaze(): Programme {
  // 16×16. The outer ring is open all the way round, so the camera can
  // patrol a loop without ever needing pathfinding.
  const MAP = [
    "################",
    "#..............#",
    "#.###..####..#.#",
    "#.#....#..#..#.#",
    "#.#.##.#.##..#.#",
    "#....#...#.....#",
    "#.##.#.###.###.#",
    "#............#.#",
    "#.#.####.###.#.#",
    "#.#....#.....#.#",
    "#.#.##.#.###.#.#",
    "#.#..#...#...#.#",
    "#.####.####..#.#",
    "#..............#",
    "#.############.#",
    "################",
  ];
  const at = (x: number, y: number) =>
    x < 0 || y < 0 || y >= MAP.length || x >= MAP[0].length ? 1 : MAP[y][x] === "#" ? 1 : 0;

  /* The patrol. A closed loop around the open ring — the camera walks it at
     constant speed and yaws to face the next leg, easing through corners so
     the turn reads as a head turn rather than a snap. */
  const ROUTE: [number, number][] = [
    [1.5, 1.5],
    [14.5, 1.5],
    [14.5, 13.5],
    [1.5, 13.5],
  ];

  // Wall tones per face — original palette, cold archive concrete with a
  // warm strip-light band. Index 0/1 = N-S vs E-W face, for free shading.
  const WALLS = [
    ["#4a5a66", "#38454e"],
    ["#5a5346", "#443f36"],
    ["#3e4a5c", "#2f3847"],
  ];

  /* Archive monoliths. Deliberately set one cell OFF the patrol route: a
     billboard standing in the corridor the camera walks down fills the
     whole raster the moment you reach it, which looks like a rendering
     failure rather than a near miss. They sit in the alcoves instead, and
     a near-plane cull covers the rest. */
  const OBJECTS: [number, number, string][] = [
    [7.5, 2.5, "#c8a85a"],
    [13.5, 7.5, "#7fd8c0"],
    [4.5, 12.5, "#c87f9a"],
    [2.5, 5.5, "#9ab8d8"],
  ];

  const st = { d: 0 };

  return {
    id: "maze",
    label: "ARCHIVE MAZE",
    reset: () => {
      st.d = 0;
    },
    draw: ({ ctx, t, dt, w, h, mono, frozen }) => {
      st.d += (frozen ? 0 : dt) * 1.15;

      /* ---- walk the route ---- */
      const legLens: number[] = [];
      let total = 0;
      for (let i = 0; i < ROUTE.length; i += 1) {
        const a = ROUTE[i];
        const b = ROUTE[(i + 1) % ROUTE.length];
        const l = Math.hypot(b[0] - a[0], b[1] - a[1]);
        legLens.push(l);
        total += l;
      }
      let travelled = st.d % total;
      let leg = 0;
      while (travelled > legLens[leg]) {
        travelled -= legLens[leg];
        leg = (leg + 1) % ROUTE.length;
      }
      const a = ROUTE[leg];
      const b = ROUTE[(leg + 1) % ROUTE.length];
      const f = travelled / legLens[leg];
      const px = a[0] + (b[0] - a[0]) * f;
      const py = a[1] + (b[1] - a[1]) * f;

      // Heading: the current leg, blended into the next one over the last
      // 1.4 units so the corner is a turn and not a cut.
      const legAngle = (i: number) => {
        const p = ROUTE[i];
        const q = ROUTE[(i + 1) % ROUTE.length];
        return Math.atan2(q[1] - p[1], q[0] - p[0]);
      };
      let ang = legAngle(leg);
      const remaining = legLens[leg] - travelled;
      if (remaining < 1.4) {
        const next = legAngle((leg + 1) % ROUTE.length);
        let delta = next - ang;
        while (delta > Math.PI) delta -= Math.PI * 2;
        while (delta < -Math.PI) delta += Math.PI * 2;
        const k = 1 - remaining / 1.4;
        ang += delta * (k * k * (3 - 2 * k));
      }
      // a slight headbob, the era's universal "you are walking" cue
      const bob = frozen ? 0 : Math.sin(st.d * 5.2) * 3.2;

      const dirX = Math.cos(ang);
      const dirY = Math.sin(ang);
      // 66° field of view
      const planeX = -dirY * 0.66;
      const planeY = dirX * 0.66;
      const horizon = h / 2 + bob;

      /* ---- ceiling and floor, banded rather than gradient ---- */
      for (let y = 0; y < h; y += 4) {
        const up = y < horizon;
        const k = Math.abs(y - horizon) / (h / 2);
        const v = Math.round((up ? 26 : 40) + k * (up ? 18 : 34));
        ctx.fillStyle = up ? `rgb(${v - 6},${v - 2},${v + 6})` : `rgb(${v + 4},${v},${v - 6})`;
        ctx.fillRect(0, y, w, 4);
      }

      /* ---- wall strips ---- */
      const stripe = 2;
      const zbuf = new Float32Array(Math.ceil(w / stripe));

      for (let sx = 0, col = 0; sx < w; sx += stripe, col += 1) {
        const camX = (2 * (sx + stripe / 2)) / w - 1;
        const rdx = dirX + planeX * camX;
        const rdy = dirY + planeY * camX;

        let mapX = Math.floor(px);
        let mapY = Math.floor(py);
        const ddx = rdx === 0 ? 1e30 : Math.abs(1 / rdx);
        const ddy = rdy === 0 ? 1e30 : Math.abs(1 / rdy);

        let stepX: number;
        let stepY: number;
        let sideX: number;
        let sideY: number;
        if (rdx < 0) {
          stepX = -1;
          sideX = (px - mapX) * ddx;
        } else {
          stepX = 1;
          sideX = (mapX + 1 - px) * ddx;
        }
        if (rdy < 0) {
          stepY = -1;
          sideY = (py - mapY) * ddy;
        } else {
          stepY = 1;
          sideY = (mapY + 1 - py) * ddy;
        }

        let side = 0;
        let hitCount = 0;
        while (hitCount < 40) {
          if (sideX < sideY) {
            sideX += ddx;
            mapX += stepX;
            side = 0;
          } else {
            sideY += ddy;
            mapY += stepY;
            side = 1;
          }
          hitCount += 1;
          if (at(mapX, mapY)) break;
        }

        // Perpendicular distance — using the euclidean one here is the
        // classic fisheye bug, and it is very visible on a curved tube.
        const dist =
          side === 0 ? (mapX - px + (1 - stepX) / 2) / rdx : (mapY - py + (1 - stepY) / 2) / rdy;
        const d = Math.max(dist, 0.05);
        zbuf[col] = d;

        const lineH = Math.min(h * 4, (h / d) * 1.05);
        const y0 = horizon - lineH / 2;

        const pal = WALLS[(Math.abs(mapX * 3 + mapY * 7) % WALLS.length + WALLS.length) % WALLS.length];
        const baseHex = pal[side];
        // depth fog, quantised into 8 steps so it bands like the era
        const fog = Math.min(1, d / 11);
        const q = Math.round((1 - fog) * 8) / 8;
        const r = parseInt(baseHex.slice(1, 3), 16);
        const g = parseInt(baseHex.slice(3, 5), 16);
        const bl = parseInt(baseHex.slice(5, 7), 16);
        ctx.fillStyle = `rgb(${Math.round(r * q + 8)},${Math.round(g * q + 9)},${Math.round(bl * q + 14)})`;
        ctx.fillRect(sx, y0, stripe, lineH);

        // Wall texture: a mortar course and a strip-light band. Two rects
        // per column is all the period hardware would have had either.
        const wallX = side === 0 ? py + d * rdy : px + d * rdx;
        const u = wallX - Math.floor(wallX);
        if (u < 0.06 || u > 0.94) {
          ctx.fillStyle = `rgba(0,0,0,${0.35 * q})`;
          ctx.fillRect(sx, y0, stripe, lineH);
        }
        ctx.fillStyle = `rgba(0,0,0,${0.22 * q})`;
        ctx.fillRect(sx, y0 + lineH * 0.46, stripe, Math.max(1, lineH * 0.035));
        ctx.fillStyle = `rgba(190,225,240,${0.12 * q})`;
        ctx.fillRect(sx, y0 + lineH * 0.1, stripe, Math.max(1, lineH * 0.03));
      }

      /* ---- objects: billboarded archive monoliths, depth-tested against
             the column buffer so they occlude correctly ---- */
      for (const [ox, oy, color] of OBJECTS) {
        const relX = ox - px;
        const relY = oy - py;
        const inv = 1 / (planeX * dirY - dirX * planeY);
        const tx = inv * (dirY * relX - dirX * relY);
        const ty = inv * (-planeY * relX + planeX * relY);
        // Near cull: closer than this a billboard is bigger than the
        // raster and reads as a wall of colour, not an object.
        if (ty <= 1.1) continue;
        const scX = Math.round((w / 2) * (1 + tx / ty));
        const size = Math.abs(Math.round(h / ty)) * 0.62;
        const y0 = horizon + size * 0.5 - size;
        const x0 = Math.round(scX - size * 0.22);
        const ww = Math.max(2, size * 0.44);
        for (let sx = x0; sx < x0 + ww; sx += stripe) {
          if (sx < 0 || sx >= w) continue;
          const col = Math.floor(sx / stripe);
          if (zbuf[col] < ty) continue;
          const fog = Math.max(0, 1 - ty / 11);
          ctx.fillStyle = color;
          ctx.globalAlpha = 0.25 + fog * 0.75;
          ctx.fillRect(sx, y0, stripe, size);
          ctx.globalAlpha = 1;
        }
        // a dark plinth so it sits on the floor rather than hovering
        ctx.fillStyle = "rgba(10,12,16,0.7)";
        ctx.fillRect(x0, y0 + size - Math.max(2, size * 0.08), ww, Math.max(2, size * 0.08));
      }

      /* ---- HUD: an original archive readout, not a game status bar ---- */
      ctx.fillStyle = "rgba(8,10,14,0.72)";
      ctx.fillRect(0, h - 26, w, 26);
      ctx.fillStyle = "#2c3a44";
      ctx.fillRect(0, h - 26, w, 1);
      text(ctx, "SECTOR", 8, h - 15, 9, "#6f8b98", mono);
      text(ctx, `${(Math.floor(px) + 1).toString().padStart(2, "0")}:${(Math.floor(py) + 1).toString().padStart(2, "0")}`, 8, h - 5, 10, "#d8e6ec", mono);
      text(ctx, "DEPTH", w / 2 - 28, h - 15, 9, "#6f8b98", mono);
      text(ctx, `${(st.d * 3.2).toFixed(0).padStart(4, "0")}M`, w / 2 - 28, h - 5, 10, "#d8e6ec", mono);
      text(ctx, "SIGNAL", w - 8, h - 15, 9, "#6f8b98", mono, "right");
      text(ctx, "GOOD", w - 8, h - 5, 10, "#7fd8a0", mono, "right");

      // compass — a real bearing off the walk heading
      const deg = ((((-ang * 180) / Math.PI + 90) % 360) + 360) % 360;
      text(ctx, `${deg.toFixed(0).padStart(3, "0")}°`, w - 8, 16, 11, "#9fc0cc", mono, "right");
    },
  };
}

/* ======================================================================== */
/* C — PIXEL ARCADE                                                         */
/* ======================================================================== */

/**
 * A 4-colour-per-sprite platformer at an 80×60 logical resolution, drawn at
 * 4× so every pixel is a hard 4×4 block. Sprites are defined as character
 * grids, which is how they were authored at the time and is also the
 * cheapest way to keep them unmistakably original.
 *
 * The character actually runs, jumps and lands on the platforms — the
 * animation is driven by a tiny physics step, not a canned cycle, so the
 * timing between the hop and the landing squash is right.
 */
function createArcade(): Programme {
  const PX = 4; // logical pixel size
  const LW = 80; // logical width
  const LH = 60;

  /* Sprites: '.' transparent, digits index into the palette. */
  const HERO = [
    "..1111..",
    ".111111.",
    ".133113.",
    ".111111.",
    "..2222..",
    ".422224.",
    ".4.22.4.",
    "..3..3..",
  ];
  const HERO_RUN = [
    "..1111..",
    ".111111.",
    ".131131.",
    ".111111.",
    "..2222..",
    ".422224.",
    "4..22..4",
    ".3....3.",
  ];
  const FOE = [
    "..5555..",
    ".556655.",
    "55555555",
    "5.5555.5",
    ".5.55.5.",
    "..5..5..",
  ];
  const PAL: Record<string, string> = {
    "1": "#f2c48a",
    "2": "#4f7fd8",
    "3": "#2a2f45",
    "4": "#d85f7a",
    "5": "#6fbf7f",
    "6": "#1c2230",
  };

  const blit = (
    ctx: CanvasRenderingContext2D,
    sprite: string[],
    lx: number,
    ly: number,
    flip = false,
  ) => {
    for (let r = 0; r < sprite.length; r += 1) {
      const row = sprite[r];
      for (let c = 0; c < row.length; c += 1) {
        const ch = row[flip ? row.length - 1 - c : c];
        if (ch === ".") continue;
        ctx.fillStyle = PAL[ch] ?? "#fff";
        ctx.fillRect((lx + c) * PX, (ly + r) * PX, PX, PX);
      }
    }
  };

  // Ground at logical y = 44; three floating platforms.
  const PLATFORMS: [number, number, number][] = [
    [14, 34, 14],
    [38, 27, 12],
    [58, 34, 14],
  ];

  const st = { x: 6, y: 36, vy: 0, dir: 1, grounded: true, score: 0, t: 0 };

  return {
    id: "arcade",
    label: "PIXEL ARCADE",
    reset: () => {
      st.x = 6;
      st.y = 36;
      st.vy = 0;
      st.dir = 1;
      st.grounded = true;
      st.score = 0;
      st.t = 0;
    },
    draw: ({ ctx, t, dt, w, h, mono, frozen }) => {
      const step = frozen ? 0 : Math.min(dt, 0.05);
      st.t += step;

      /* ---- physics, in logical pixels per second ---- */
      st.x += st.dir * 22 * step;
      if (st.x > LW - 10) st.dir = -1;
      if (st.x < 2) st.dir = 1;

      st.vy += 150 * step;
      st.y += st.vy * step;

      const feet = st.y + 8;
      let landed = false;
      // ground
      if (feet >= 44) {
        st.y = 36;
        st.vy = 0;
        landed = true;
      }
      // platforms, only from above
      for (const [pxx, pyy, pw] of PLATFORMS) {
        if (st.vy > 0 && st.x + 6 > pxx && st.x + 2 < pxx + pw && feet >= pyy && feet <= pyy + 6) {
          st.y = pyy - 8;
          st.vy = 0;
          landed = true;
        }
      }
      st.grounded = landed;
      // hop on a fixed cadence while grounded
      if (landed && Math.sin(st.t * 2.3) > 0.72) {
        st.vy = -62;
        st.score += 1;
      }

      /* ---- background: three parallax bands ---- */
      const sky = ctx.createLinearGradient(0, 0, 0, h);
      sky.addColorStop(0, "#1b1a3e");
      sky.addColorStop(0.6, "#3a2a55");
      sky.addColorStop(1, "#5c3a5e");
      ctx.fillStyle = sky;
      ctx.fillRect(0, 0, w, h);

      // stars, on a fixed lattice so they do not swim
      ctx.fillStyle = "#cfc6f0";
      for (let i = 0; i < 26; i += 1) {
        const sxp = Math.floor(hash(i * 2.3) * LW);
        const syp = Math.floor(hash(i * 7.7) * 22);
        if (Math.sin(st.t * 2 + i) > -0.3) ctx.fillRect(sxp * PX, syp * PX, PX, PX);
      }

      // far hills — stepped, never diagonal
      ctx.fillStyle = "#2c2450";
      for (let i = 0; i < LW; i += 1) {
        const hh = Math.round(4 + Math.sin(i * 0.19 + 1.3) * 3 + Math.sin(i * 0.07) * 2);
        ctx.fillRect(i * PX, (34 - hh) * PX, PX, hh * PX + 40);
      }
      ctx.fillStyle = "#3a2c5e";
      const drift = frozen ? 0 : (st.t * 3) % LW;
      for (let i = 0; i < LW; i += 1) {
        const k = (i + drift) % LW;
        const hh = Math.round(3 + Math.sin(k * 0.31) * 2.4);
        ctx.fillRect(i * PX, (40 - hh) * PX, PX, hh * PX + 40);
      }

      /* ---- ground ---- */
      ctx.fillStyle = "#4a3a2c";
      ctx.fillRect(0, 44 * PX, w, h - 44 * PX);
      ctx.fillStyle = "#6b5540";
      ctx.fillRect(0, 44 * PX, w, PX);
      ctx.fillStyle = "#382c22";
      for (let i = 0; i < LW; i += 2) {
        if (hash(i * 5.1) > 0.6) ctx.fillRect(i * PX, 47 * PX, PX, PX);
      }

      /* ---- platforms ---- */
      for (const [pxx, pyy, pw] of PLATFORMS) {
        ctx.fillStyle = "#7a6248";
        ctx.fillRect(pxx * PX, pyy * PX, pw * PX, 2 * PX);
        ctx.fillStyle = "#a08760";
        ctx.fillRect(pxx * PX, pyy * PX, pw * PX, PX);
        ctx.fillStyle = "#3d3025";
        ctx.fillRect(pxx * PX, (pyy + 2) * PX, pw * PX, PX);
      }

      /* ---- collectibles: a blinking token above each platform ---- */
      for (let i = 0; i < PLATFORMS.length; i += 1) {
        const [pxx, pyy, pw] = PLATFORMS[i];
        if (Math.sin(st.t * 4 + i * 2) < -0.5) continue;
        const cx = Math.round(pxx + pw / 2);
        const cy = pyy - 5 + Math.round(Math.sin(st.t * 3 + i) * 1);
        ctx.fillStyle = "#f2d76a";
        ctx.fillRect(cx * PX, cy * PX, 2 * PX, 2 * PX);
        ctx.fillStyle = "#fff4c0";
        ctx.fillRect(cx * PX, cy * PX, PX, PX);
      }

      /* ---- foe patrolling the ground ---- */
      const foeX = 40 + Math.round(Math.sin(st.t * 0.9) * 22);
      blit(ctx, FOE, foeX, 38, Math.cos(st.t * 0.9) < 0);

      /* ---- hero ---- */
      const running = st.grounded && Math.floor(st.t * 8) % 2 === 0;
      blit(ctx, running ? HERO_RUN : HERO, Math.round(st.x), Math.round(st.y), st.dir < 0);

      /* ---- HUD ---- */
      ctx.fillStyle = "rgba(12,10,26,0.8)";
      ctx.fillRect(0, 0, w, 22);
      text(ctx, "SCORE", 8, 10, 8, "#8f86c0", mono);
      text(ctx, `${(st.score * 120).toString().padStart(6, "0")}`, 8, 20, 10, "#f2e9c0", mono);
      text(ctx, "STAGE 1-1", w / 2, 16, 10, "#f2e9c0", mono, "center");
      // three lives, as pixel hearts
      for (let i = 0; i < 3; i += 1) {
        ctx.fillStyle = "#d85f7a";
        const hx = w - 12 - i * 16;
        ctx.fillRect(hx - 6, 6, 3, 3);
        ctx.fillRect(hx, 6, 3, 3);
        ctx.fillRect(hx - 6, 9, 9, 3);
        ctx.fillRect(hx - 4, 12, 5, 3);
      }
    },
  };
}

/* ======================================================================== */
/* D — SIGNAL / VOYAGE ARCHIVE                                              */
/* ======================================================================== */

/**
 * The breathing space between programmes: an archive test card. Calibration
 * bars, a hand-projected rotating wireframe, drifting coordinates and a
 * blinking carrier status.
 *
 * This is where the Voyagerscape identity is allowed to speak — but only in
 * the language of the object. It is a test card the hardware would have
 * generated, not a logo screen.
 */
function createSignal(): Programme {
  // An octahedron-capped prism: enough vertices to read as a solid under
  // rotation, few enough to look like a 1998 vector demo.
  const V: [number, number, number][] = [
    [0, 1.25, 0],
    [0, -1.25, 0],
    [0.85, 0.35, 0.85],
    [-0.85, 0.35, 0.85],
    [-0.85, 0.35, -0.85],
    [0.85, 0.35, -0.85],
    [0.85, -0.35, 0.85],
    [-0.85, -0.35, 0.85],
    [-0.85, -0.35, -0.85],
    [0.85, -0.35, -0.85],
  ];
  const E: [number, number][] = [
    [0, 2], [0, 3], [0, 4], [0, 5],
    [2, 3], [3, 4], [4, 5], [5, 2],
    [2, 6], [3, 7], [4, 8], [5, 9],
    [6, 7], [7, 8], [8, 9], [9, 6],
    [1, 6], [1, 7], [1, 8], [1, 9],
  ];

  const BARS = ["#c0c0c0", "#c0c000", "#00c0c0", "#00c000", "#c000c0", "#c00000", "#0000c0"];

  return {
    id: "signal",
    label: "VOYAGE ARCHIVE",
    reset: () => {},
    draw: ({ ctx, t, w, h, mono, frozen }) => {
      ctx.fillStyle = "#0a0d12";
      ctx.fillRect(0, 0, w, h);

      /* ---- calibration bars, top third ---- */
      const bw = w / BARS.length;
      for (let i = 0; i < BARS.length; i += 1) {
        ctx.fillStyle = BARS[i];
        ctx.fillRect(i * bw, 0, Math.ceil(bw), 46);
      }
      // greyscale wedge beneath them
      for (let i = 0; i < 10; i += 1) {
        const v = Math.round((i / 9) * 210);
        ctx.fillStyle = `rgb(${v},${v},${v})`;
        ctx.fillRect((i * w) / 10, 46, Math.ceil(w / 10), 8);
      }

      /* ---- grid field ---- */
      ctx.strokeStyle = "rgba(90,140,160,0.22)";
      ctx.lineWidth = 1;
      ctx.beginPath();
      for (let x = 0; x <= w; x += 20) {
        ctx.moveTo(x + 0.5, 58);
        ctx.lineTo(x + 0.5, h - 30);
      }
      for (let y = 58; y <= h - 30; y += 20) {
        ctx.moveTo(0, y + 0.5);
        ctx.lineTo(w, y + 0.5);
      }
      ctx.stroke();

      /* ---- rotating wireframe, projected by hand ---- */
      const ax = frozen ? 0.4 : t * 0.55;
      const ay = frozen ? 0.9 : t * 0.83;
      const cx = w / 2;
      const cy = 142;
      const scale = 42;
      const proj = V.map(([x, y, z]) => {
        // rotate Y then X
        const x1 = x * Math.cos(ay) - z * Math.sin(ay);
        const z1 = x * Math.sin(ay) + z * Math.cos(ay);
        const y2 = y * Math.cos(ax) - z1 * Math.sin(ax);
        const z2 = y * Math.sin(ax) + z1 * Math.cos(ax);
        const p = 3.4 / (3.4 + z2);
        return [cx + x1 * scale * p, cy + y2 * scale * p, z2] as [number, number, number];
      });

      ctx.lineWidth = 1;
      for (const [i, j] of E) {
        const a = proj[i];
        const b = proj[j];
        const depth = (a[2] + b[2]) / 2;
        const k = Math.max(0.15, Math.min(1, 1 - (depth + 1.3) / 3));
        ctx.strokeStyle = `rgba(150,235,255,${0.25 + k * 0.7})`;
        ctx.beginPath();
        ctx.moveTo(Math.round(a[0]) + 0.5, Math.round(a[1]) + 0.5);
        ctx.lineTo(Math.round(b[0]) + 0.5, Math.round(b[1]) + 0.5);
        ctx.stroke();
      }
      // vertices as hard pixels
      ctx.fillStyle = "#e6fbff";
      for (const p of proj) ctx.fillRect(Math.round(p[0]) - 1, Math.round(p[1]) - 1, 2, 2);

      /* ---- readouts ---- */
      const lat = 51.5074 + Math.sin(t * 0.31) * 0.42;
      const lon = -0.1278 + Math.cos(t * 0.24) * 0.51;
      text(ctx, "VOYAGE ARCHIVE", 8, 70, 11, "#8fe8ff", mono);
      text(ctx, "SYSTEM 02", 8, 82, 9, "#4d8496", mono);

      text(ctx, "LAT", 8, h - 62, 9, "#4d8496", mono);
      text(ctx, `${lat >= 0 ? "+" : ""}${lat.toFixed(4)}`, 34, h - 62, 9, "#c8f0ff", mono);
      text(ctx, "LON", 8, h - 50, 9, "#4d8496", mono);
      text(ctx, `${lon >= 0 ? "+" : ""}${lon.toFixed(4)}`, 34, h - 50, 9, "#c8f0ff", mono);

      text(ctx, "MODE", w - 8, h - 62, 9, "#4d8496", mono, "right");
      text(ctx, "EXPLORE", w - 8, h - 50, 9, "#c8f0ff", mono, "right");

      // carrier bar: a live level meter, blinking when it dips
      const lvl = 0.55 + Math.sin(t * 1.9) * 0.2 + Math.sin(t * 4.3) * 0.08;
      ctx.fillStyle = "#16242c";
      ctx.fillRect(8, h - 38, w - 16, 7);
      for (let i = 0; i < 24; i += 1) {
        const on = i / 24 < lvl;
        ctx.fillStyle = on ? (i > 18 ? "#ffd06a" : "#6fe0a4") : "#22363e";
        ctx.fillRect(10 + i * ((w - 20) / 24), h - 37, (w - 20) / 24 - 2, 5);
      }

      const blink = frozen || Math.sin(t * 5) > -0.2;
      text(ctx, "SIGNAL", 8, h - 12, 10, "#4d8496", mono);
      text(ctx, blink ? "LOCKED" : "", 56, h - 12, 10, "#7fd8a0", mono);
      text(
        ctx,
        `T+${Math.floor(t * 10 + 1204).toString().padStart(6, "0")}`,
        w - 8,
        h - 12,
        10,
        "#8fb7c8",
        mono,
        "right",
      );
    },
  };
}

/* ------------------------------------------------------------------------ */

/** Build a fresh, independent set. Nothing here is module-level state. */
export function createProgrammes(): Programme[] {
  return [createDrive(), createMaze(), createArcade(), createSignal()];
}
